function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 5000) return 'nums needs 1 to 5000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -5000 || v > 5000)) return 'Each value is a whole number from -5000 to 5000.';
  let drops = 0;
  for (let i = 0; i < nums.length; i++) if (nums[i] > nums[(i + 1) % nums.length]) drops++;
  if (drops > 1) return 'nums must be a sorted list that has been rotated.';
  return null;
}

