function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1500 + pick(501) : 1 + pick(10);
  const span = size === 'large' ? (rand() < 0.5 ? 10001 : 5) : (rand() < 0.5 ? 4 : 10001);
  const sorted = Array.from({ length: n }, () => pick(span) - Math.floor(span / 2)).sort((a, b) => a - b);
  if (size === 'large' && rand() < 0.2) {
    // Mostly equal values with a single dip force the slow, one-step shrinking path.
    sorted.fill(7);
    sorted[0] = -3;
  }
  const k = pick(n);
  return [[...sorted.slice(k), ...sorted.slice(0, k)]];
}
